import{_ as e,o as d,c as a,a2 as t}from"./chunks/framework.CuUVYbLV.js";const _=JSON.parse('{"title":"协作图（已移除）","description":"声明式 collaboration 块的移除范围与迁移要点 — v1.8.0 起多代理工作流只跑命令式 graph_* 引擎","frontmatter":{"title":"协作图（已移除）","description":"声明式 collaboration 块的移除范围与迁移要点 — v1.8.0 起多代理工作流只跑命令式 graph_* 引擎"},"headers":[],"relativePath":"02-Guide/collaboration-graph.md","filePath":"02-Guide/collaboration-graph.md"}'),c={name:"02-Guide/collaboration-graph.md"};function r(l,o,i,n,h,p){return d(),a("div",null,[...o[0]||(o[0]=[t('<h1 id="协作图-collaboration-graph-已移除" tabindex="-1">协作图（Collaboration Graph，已移除） <a class="header-anchor" href="#协作图-collaboration-graph-已移除" aria-label="Permalink to &quot;协作图（Collaboration Graph，已移除）&quot;">​</a></h1><p>协作图是 rolebox v0.x–v1.7 的声明式多代理工作流写法：在 <code>role.yaml</code> 中用 <code>collaboration:</code> 块描述拓扑、参与者与迭代上限，启动时由解析器转成图并自动推进。<strong>v1.8.0 起该子系统被整体移除</strong>，本页只记录它曾是什么、删掉了什么，以及旧配置如何改写。</p><blockquote><p>前置：<a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a>｜相关：<a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a>、<a href="/rolebox-docs/04-Advanced/graph-engine.html">图执行引擎</a></p></blockquote><h2 id="被移除的是什么" tabindex="-1">被移除的是什么 <a class="header-anchor" href="#被移除的是什么" aria-label="Permalink to &quot;被移除的是什么&quot;">​</a></h2><p><code>collaboration:</code> 是 <code>role.yaml</code> 顶层的一个声明式（declarative）块——用少量字段描述整张工作流，而不是逐条发命令。它的字段有：</p><table tabindex="0"><thead><tr><th>字段</th><th>作用</th></tr></thead><tbody><tr><td><code>topology</code></td><td>预设拓扑：<code>pipeline</code>（串行）、<code>review-loop</code>（循环）、<code>star</code>（并行）</td></tr><tr><td><code>flow</code></td><td>自定义数据流：谁把结果传给谁</td></tr><tr><td><code>agents</code></td><td>参与该工作流的子代理列表</td></tr><tr><td><code>max_iterations</code></td><td>工作流循环轮数上限</td></tr><tr><td><code>termination</code></td><td>终止条件，用 <code>any_of</code>（任一满足即止）/ <code>all_of</code>（全部满足才止）组合</td></tr></tbody></table><h2 id="移除了什么范围" tabindex="-1">移除了什么范围 <a class="header-anchor" href="#移除了什么范围" aria-label="Permalink to &quot;移除了什么范围&quot;">​</a></h2><p>v1.8.0 把声明式协作词汇表整体删除，范围可归为四类：</p><table tabindex="0"><thead><tr><th>类别</th><th>被删除的对象</th></tr></thead><tbody><tr><td><code>role.yaml</code> schema</td><td><code>collaboration:</code> 块本身（<code>topology</code> / <code>flow</code> / <code>agents</code> / <code>max_iterations</code> / <code>termination</code>）</td></tr><tr><td>类型词汇表</td><td><code>TerminationDecl</code> / <code>TerminationCondition</code> / <code>LoopCondition</code> / <code>TerminationConfig</code></td></tr><tr><td>扩展点与工具参数</td><td><code>termination_conditions</code> 扩展点、<code>graph_add_loop</code> 的 <code>termination</code> 参数</td></tr><tr><td>代码模块</td><td>移植过来的 <code>collaboration-*</code> 图模块（advance / state / store / bridge / validator）与 v1 残留模块</td></tr></tbody></table><p>v1 graph-session 运行时状态读取器及其 compaction 与 <code>monitor</code> 界面、四个示例协作角色也一并删除。v1.9.0 的 <code>role.yaml</code> 里不再有任何声明式协作字段，也没有自动转换器。</p><h2 id="现在用什么" tabindex="-1">现在用什么 <a class="header-anchor" href="#现在用什么" aria-label="Permalink to &quot;现在用什么&quot;">​</a></h2><p>多代理编排只跑命令式（imperative）<code>graph_*</code> 引擎：<code>graph_create</code> 建图 → <code>graph_add_node</code> 加节点 → <code>graph_add_edge</code> 连边 → <code>graph_add_loop</code> 声明有界循环组 → <code>graph_run</code> 启动；<code>graph_status</code> 观测、<code>graph_approve</code> 审批、<code>graph_cancel</code> 取消。节点是角色无关的 <code>{agent, prompt}</code> 元组，完整用法见<a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a>。</p><h2 id="迁移对照要点" tabindex="-1">迁移对照要点 <a class="header-anchor" href="#迁移对照要点" aria-label="Permalink to &quot;迁移对照要点&quot;">​</a></h2><p>旧配置到新写法的四条要点（v0.x → v1.9.0 的完整变更清单见<a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a>）：</p><ul><li><code>topology</code> → <code>graph_create</code> + <code>graph_add_node</code> + <code>graph_add_edge</code> 手工搭出同一拓扑。</li><li><code>agents</code> → 每个 <code>graph_add_node</code> 的 <code>agent</code> 字段。</li><li><code>flow</code> → <code>graph_add_edge</code>，按需指定 <code>type</code>（<code>always</code> / <code>on_signal</code> / <code>on_condition</code>）。</li><li><code>max_iterations</code> 与 <code>termination</code> → <code>graph_add_loop</code> 的 <code>max_traversals</code> 硬上限，配合 <code>graph_status</code> 观测与 <code>graph_cancel</code> 终止。</li></ul><p>迁移是配置改写，不是自动转换：rolebox 没有自动迁移子命令，删掉 <code>collaboration:</code> 块后按图文档手写。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/rolebox-docs/06-Appendix/migration.html">迁移对照</a> — v0.x → v1.9.0 的破坏性变更清单与升级指南</li><li><a href="/rolebox-docs/04-Advanced/termination-conditions.html">终止条件（已移除）</a> — 终止子系统的移除范围与仍生效的终止语义</li><li><a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a> — 用 <code>graph_*</code> 工具编写现行多代理工作流</li></ul>',18)])])}const g=e(c,[["render",r]]);export{_ as __pageData,g as default};
